mapper.select:
SELECT TEMPLATE_ID, TEMPLATE_CODE, TEMPLATE_NAME, TEMPLATE_TYPE, STATUS, VERSION, DESCRIPTION, VOUCHER_TYPE, USED_COUNT, BOOK_ID, TENANT_ID, CREATOR_ID, CREATOR_NAME, CREATE_TIME, UPDATE_TIME FROM TBL_VOUCHER_TEMPLATE WHERE 1=1
AND BOOK_ID = #{param.bookId}
AND TENANT_ID = #{param.tenantId}
AND (TEMPLATE_CODE LIKE '%'||#{param.keyword}||'%' OR TEMPLATE_NAME LIKE '%'||#{param.keyword}||'%' OR DESCRIPTION LIKE '%'||#{param.keyword}||'%')
AND TEMPLATE_TYPE = #{param.templateType}
AND STATUS = #{param.status}
AND CREATOR_ID = #{param.creatorId}
AND CREATE_TIME >= TO_DATE(#{param.startDate}, 'YYYY-MM-DD')
AND CREATE_TIME <= TO_DATE(#{param.endDate}, 'YYYY-MM-DD') + 1
ORDER BY CREATE_TIME DESC OFFSET #{param.offset} ROWS FETCH NEXT #{param.pageSize} ROWS ONLY

SELECT COUNT(1)
FROM TBL_VOUCHER_TEMPLATE
WHERE 1=1

    AND BOOK_ID = #{param.bookId}


    AND TENANT_ID = #{param.tenantId}


    AND (TEMPLATE_CODE LIKE '%'||#{param.keyword}||'%'
         OR TEMPLATE_NAME LIKE '%'||#{param.keyword}||'%'
         OR DESCRIPTION LIKE '%'||#{param.keyword}||'%')


    AND TEMPLATE_TYPE = #{param.templateType}


    AND STATUS = #{param.status}


    AND CREATOR_ID = #{param.creatorId}


    AND CREATE_TIME >= TO_DATE(#{param.startDate}, 'YYYY-MM-DD')


    AND CREATE_TIME <= TO_DATE(#{param.endDate}, 'YYYY-MM-DD') + 1

SELECT COUNT(1)
FROM TBL_VOUCHER_TEMPLATE
WHERE TEMPLATE_CODE = #{templateCode}

    AND TEMPLATE_ID != #{excludeId}

